class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.12.0/commando_0.12.0_darwin_arm64.tar.gz"
      sha256 "8e7dee645a3d033e1209e51f8dc3cd847a33ab376ecdffe17698d2bc4ba6a4fd"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.12.0/commando_0.12.0_darwin_amd64.tar.gz"
      sha256 "04dfccbab45f69d52b8c2d64c0cb74b14f130fc420d7e08a5e7efab087aba3f6"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.12.0/commando_0.12.0_linux_arm64.tar.gz"
      sha256 "5712c325808a9792d4f3667d3dfc9cc53b874f72acab8071b89e8b62d98a9d00"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.12.0/commando_0.12.0_linux_amd64.tar.gz"
      sha256 "705575c148caca413b7bec1ed2e5493495ba5e3907ac4e3f2e492cb4cab2187f"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
